package com.mybank.pbac.config; import com.mybank.pbac.model.*; import com.mybank.pbac.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*;
@Configuration public class SeedData {@Bean CommandLineRunner seed(AttributeDefinitionRepository a,ObligationRepository o){return args->{if(a.count()==0){for(String k:new String[]{"subject.role","action.tool","resource.classification","context.ipAddress","context.country","context.riskScore"}){AttributeDefinition d=new AttributeDefinition();d.setAttributeKey(k);d.setDisplayName(k);d.setDataType(k.contains("ipAddress")?AttributeDataType.IP_ADDRESS:k.contains("riskScore")?AttributeDataType.NUMBER:AttributeDataType.STRING);a.save(d);}} if(o.count()==0){for(String[] x:new String[][]{{"mask_customer_id","Mask customer ID"},{"audit_access","Audit access"},{"require_human_approval","Require human approval"}}){Obligation b=new Obligation();b.setCode(x[0]);b.setName(x[1]);o.save(b);}}};}}
